	@Test
	void staleMergeHintKeepsVolatileRightOperandOnReplay() {
		AtomicBoolean orderRead = new AtomicBoolean();
		StatementPattern left = trackingPattern("join", "urn:test:left", "left", orderRead);
		StatementPattern rightPattern = trackingPattern("join", "urn:test:right", "right", orderRead);
		left.setOrder(left.getSubjectVar());
		rightPattern.setOrder(rightPattern.getSubjectVar());
		Extension volatileRight = new Extension(rightPattern,
				new ExtensionElem(new FunctionCall("STRUUID"), "generated"));
		Join join = new Join(left, volatileRight);
		join.setMergeJoin(true);
		join.setAlgorithm(InnerMergeJoinIterator.class.getSimpleName());
		join.setOrder(new Var("join"));
		AtomicInteger rightEvaluationCount = new AtomicInteger();
		EvaluationStrategy strategy = mock(EvaluationStrategy.class);
		when(strategy.precompile(eq(left), any(QueryEvaluationContext.class))).thenAnswer(invocation -> {
			assertTrue(orderRead.get(), "stale child ordering must be resolved before child precompilation");
			return fixedRows("join", "urn:test:key");
		});
		QueryEvaluationStep volatileRightStep = bindings -> {
			rightEvaluationCount.incrementAndGet();
			return fixedRows("join", "urn:test:key").evaluate(bindings);
		};
		when(strategy.precompile(eq(volatileRight), any(QueryEvaluationContext.class))).thenAnswer(invocation -> {
			assertTrue(orderRead.get(), "stale child ordering must be resolved before child precompilation");
			return volatileRightStep;
		});

		JoinQueryEvaluationStep step = new JoinQueryEvaluationStep(strategy, join, mergeContext());
		List<BindingSet> rows = collect(step.evaluate(EmptyBindingSet.getInstance()));

		assertEquals(MaterializedReplayJoinIterator.class.getSimpleName(), join.getAlgorithmName());
		assertEquals(1, rightEvaluationCount.get(), "replay must evaluate the volatile right operand once");
		assertEquals(1, rows.size());
	}

