	@Test
	void nestedParentMergeRetainsMergeAfterChildReplayFallback() {
		StatementPattern childLeft = pattern("join", "urn:test:child-left", "child-left");
		StatementPattern childRightPattern = pattern("join", "urn:test:child-right", "child-right");
		childLeft.setOrder(childLeft.getSubjectVar());
		childRightPattern.setOrder(childRightPattern.getSubjectVar());
		Extension childVolatileRight = new Extension(childRightPattern,
				new ExtensionElem(new FunctionCall("STRUUID"), "childGenerated"));
		Join childJoin = new Join(childLeft, childVolatileRight);
		childJoin.setMergeJoin(true);
		childJoin.setOrder(new Var("join"));

		StatementPattern parentRight = pattern("join", "urn:test:parent-right", "parent-right");
		parentRight.setOrder(parentRight.getSubjectVar());
		Join parentJoin = new Join(childJoin, parentRight);
		parentJoin.setMergeJoin(true);
		parentJoin.setOrder(new Var("join"));

		AtomicInteger childRightEvaluationCount = new AtomicInteger();
		EvaluationStrategy strategy = mock(EvaluationStrategy.class);
		when(strategy.precompile(eq(childLeft), any(QueryEvaluationContext.class)))
				.thenReturn(fixedRows("join", "urn:test:key"));
		when(strategy.precompile(eq(childVolatileRight), any(QueryEvaluationContext.class))).thenReturn(bindings -> {
			childRightEvaluationCount.incrementAndGet();
			return fixedRows("join", "urn:test:key").evaluate(bindings);
		});
		JoinQueryEvaluationStep childStep = new JoinQueryEvaluationStep(strategy, childJoin, mergeContext());
		when(strategy.precompile(eq(childJoin), any(QueryEvaluationContext.class))).thenReturn(childStep);
		when(strategy.precompile(eq(parentRight), any(QueryEvaluationContext.class)))
				.thenReturn(fixedRows("join", "urn:test:key"));

		JoinQueryEvaluationStep parentStep = new JoinQueryEvaluationStep(strategy, parentJoin, mergeContext());
		List<BindingSet> rows = collect(parentStep.evaluate(EmptyBindingSet.getInstance()));

		assertEquals(MaterializedReplayJoinIterator.class.getSimpleName(), childJoin.getAlgorithmName());
		assertEquals(InnerMergeJoinIterator.class.getSimpleName(), parentJoin.getAlgorithmName());
		assertEquals(1, childRightEvaluationCount.get(), "the child replay must evaluate its volatile right once");
		assertEquals(1, rows.size());
	}

