	@Test
	void mixedUnionDoesNotConsumeNonRepeatableLeftBeforeResultConsumption() {
		Extension left = new Extension(values("x", "left"),
				new ExtensionElem(new FunctionCall("STRUUID"), "seed"));
		Service mappingBranch = new Service(
				Var.of("serviceRef", SimpleValueFactory.getInstance().createIRI("urn:test:mixed-cancel")),
				new StatementPattern(Var.of("x"), Var.of("predicate"), Var.of("object")),
				"{ ?x ?predicate ?object }", Map.of(), null, false);
		Extension independentBranch = independentUuidBranch();
		Union mixedUnion = new Union(mappingBranch, independentBranch);
		Join join = new Join(left, mixedUnion);

		AtomicInteger leftEvaluationCount = new AtomicInteger();
		AtomicInteger leftHasNextCount = new AtomicInteger();
		AtomicInteger leftCloseCount = new AtomicInteger();
		QueryBindingSet leftRow = row("x", "urn:test:left");
		leftRow.addBinding("seed", SimpleValueFactory.getInstance().createLiteral("seed"));
		DefaultEvaluationStrategy strategy = defaultStrategySpy();
		QueryEvaluationStep leftStep = bindings -> {
			leftEvaluationCount.incrementAndGet();
			return new CloseableIteratorIteration<>(List.of(leftRow).iterator()) {
				@Override
				public boolean hasNext() {
					leftHasNextCount.incrementAndGet();
					return super.hasNext();
				}

				@Override
				protected void handleClose() {
					leftCloseCount.incrementAndGet();
					super.handleClose();
				}
			};
		};
		doReturn(leftStep).when(strategy).precompile(same(left.getArg()), any(QueryEvaluationContext.class));
		doReturn(QueryEvaluationStep.empty()).when(strategy)
				.precompile(same(mappingBranch),
						any(QueryEvaluationContext.class));
		doReturn(QueryEvaluationStep.empty()).when(strategy)
				.precompile(same(independentBranch.getArg()),
						any(QueryEvaluationContext.class));

		JoinQueryEvaluationStep step = new JoinQueryEvaluationStep(strategy, join, mergeContext());
		try (CloseableIteration<BindingSet> result = step.evaluate(EmptyBindingSet.getInstance())) {
			result.close();
		}

		assertEquals(0, leftHasNextCount.get(),
				"cancellation before consumption must not drain a non-repeatable left operand");
		assertEquals(leftEvaluationCount.get(), leftCloseCount.get(),
				"cancellation must close a left operand exactly once if it was opened");
	}

