	void mixedUnionClosesOpenedBranchWhenLaterBranchOpeningFails() {
		Service mappingBranch = new Service(
				Var.of("serviceRef", SimpleValueFactory.getInstance().createIRI("urn:test:open-failure")),
				new StatementPattern(Var.of("x"), Var.of("predicate"), Var.of("mapped")),
				"{ ?x ?predicate ?mapped }", Map.of(), null, false);
		Extension independentBranch = independentUuidBranch();
		Union mixedUnion = new Union(mappingBranch, independentBranch);
		BindingSetAssignment left = values("x", "left");
		Join join = new Join(left, mixedUnion);

		AtomicInteger mappingCloseCount = new AtomicInteger();
		QueryEvaluationException expected = new QueryEvaluationException("independent branch failed while opening");
		DefaultEvaluationStrategy strategy = defaultStrategySpy();
		doReturn(fixedRows("x", "urn:test:left")).when(strategy)
				.precompile(same(left),
						any(QueryEvaluationContext.class));
		doReturn((QueryEvaluationStep) bindings -> new CloseableIteratorIteration<>(
				List.of(row("mapped", "urn:test:value")).iterator()) {
			@Override
			protected void handleClose() {
				mappingCloseCount.incrementAndGet();
				super.handleClose();
			}
		}).when(strategy).precompile(same(mappingBranch), any(QueryEvaluationContext.class));
		doReturn((QueryEvaluationStep) bindings -> {
			throw expected;
		}).when(strategy).precompile(same(independentBranch.getArg()), any(QueryEvaluationContext.class));

		JoinQueryEvaluationStep step = new JoinQueryEvaluationStep(strategy, join, mergeContext());
		QueryEvaluationException actual;
		try (CloseableIteration<BindingSet> result = step.evaluate(EmptyBindingSet.getInstance())) {
			actual = assertThrows(QueryEvaluationException.class, () -> {
				while (result.hasNext()) {
					result.next();
				}
			});
		}

		assertSame(expected, actual);
		assertEquals(1, mappingCloseCount.get(), "a later branch failure must close an already-open branch");
	}

	@Test
	void nonemptyMixedUnionDoesNotProbeMappingBranchAfterSuccessfulInput() {
		TupleFunctionCall mappingBranch = new TupleFunctionCall();
		mappingBranch.setURI("urn:test:mapping");
		mappingBranch.addResultVar(Var.of("u"));
		Extension independentBranch = independentUuidBranch();
		Union mixedUnion = new Union(mappingBranch, independentBranch);
		BindingSetAssignment outer = new BindingSetAssignment();
		outer.setBindingSets(List.of(row("x", "urn:test:one"), row("x", "urn:test:two")));
		Join join = new Join(outer, mixedUnion);

		AtomicInteger mappingCalls = new AtomicInteger();
		AtomicInteger unboundProbeCalls = new AtomicInteger();
		DefaultEvaluationStrategy strategy = defaultStrategySpy();
		doReturn(fixedRows(row("x", "urn:test:one"), row("x", "urn:test:two"))).when(strategy)
				.precompile(same(outer), any(QueryEvaluationContext.class));
		doReturn((QueryEvaluationStep) bindings -> {
			mappingCalls.incrementAndGet();
			if (!bindings.hasBinding("x")) {
				unboundProbeCalls.incrementAndGet();
			}
			Value resultValue = bindings.hasBinding("x")
					? bindings.getValue("x")
					: SimpleValueFactory.getInstance().createIRI("urn:test:probe");
			return fixedRows(row("u", resultValue)).evaluate(bindings);
		}).when(strategy).precompile(same(mappingBranch), any(QueryEvaluationContext.class));
		JoinQueryEvaluationStep step = new JoinQueryEvaluationStep(strategy, join, mergeContext());
		assertEquals(4, collect(step.evaluate(EmptyBindingSet.getInstance())).size());
		assertEquals(2, mappingCalls.get(), "a successful nonempty join needs one mapping call per input row");
		assertEquals(0, unboundProbeCalls.get(), "successful nonempty inputs must not trigger an empty-input probe");
	}

	@Test
	void emptyMixedJoinUsesBoundedFatalServiceProbe() {
		Service service = new Service(
				Var.of("serviceRef", SimpleValueFactory.getInstance().createIRI("urn:test:bounded-probe")),
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")), "{ ?s ?p ?o }", Map.of(), null,
				false);
		Union right = new Union(service, values("marker", "independent"));
		Join join = new Join(new EmptySet(), right);
		AtomicInteger serviceOpenCount = new AtomicInteger();
		AtomicInteger serviceHasNextCount = new AtomicInteger();
		AtomicInteger serviceNextCount = new AtomicInteger();
		AtomicInteger serviceCloseCount = new AtomicInteger();
		FederatedService federatedService = mock(FederatedService.class);
		when(federatedService.select(eq(service), anySet(), any(BindingSet.class), eq(service.getBaseURI())))
				.thenAnswer(invocation -> {
					serviceOpenCount.incrementAndGet();
					List<BindingSet> remoteRows = List.of(row("s", "urn:test:remote-1"),
							row("s", "urn:test:remote-2"), row("s", "urn:test:remote-3"));
					return new CloseableIteration<>() {
						private int index;

						@Override
						public boolean hasNext() {
							serviceHasNextCount.incrementAndGet();
							return index < remoteRows.size();
						}

						@Override
						public BindingSet next() {
							if (index >= remoteRows.size()) {
								throw new NoSuchElementException();
							}
							serviceNextCount.incrementAndGet();
							return remoteRows.get(index++);
						}

						@Override
						public void remove() {
							throw new UnsupportedOperationException();
						}

						@Override
						public void close() {
							serviceCloseCount.incrementAndGet();
						}
					};
				});

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(),
				serviceUrl -> federatedService);

		List<BindingSet> rows = collect(strategy.precompile(join)
				.evaluate(EmptyBindingSet.getInstance()));

		assertTrue(rows.isEmpty());
		assertEquals(1, serviceOpenCount.get(), "the fatal probe must open the SERVICE once");
		assertTrue(serviceHasNextCount.get() >= 1, "the fatal probe must reach the remote result");
		assertTrue(serviceNextCount.get() <= 1, "the fatal probe must consume at most one remote row");
		assertEquals(1, serviceCloseCount.get(), "the bounded probe must close its remote result once");
	}

	@Test
	void emptyCorrelatedPrefixProbesIndependentUnionOnceBeforeLaterRows() {
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		IRI correlatedEndpoint = valueFactory.createIRI("urn:test:probe-correlated-a");
		IRI independentEndpoint = valueFactory.createIRI("urn:test:probe-independent-b");
		IRI xA = valueFactory.createIRI("urn:test:a");
		IRI xB = valueFactory.createIRI("urn:test:b");
		Service correlated = new Service(Var.of("serviceRefA", correlatedEndpoint),
				new StatementPattern(Var.of("x"), Var.of("lp"), Var.of("lo")),
				"{ ?x ?lp ?lo }", Map.of(), null, false);
		Service independent = new Service(Var.of("serviceRefB", independentEndpoint),
				new StatementPattern(Var.of("r"), Var.of("rp"), Var.of("ro")),
				"{ ?r ?rp ?ro }", Map.of(), null, false);
		BindingSetAssignment outer = new BindingSetAssignment();
		outer.setBindingSets(List.of(row("x", xA), row("x", xB)));
		Union right = new Union(independent, values("marker", "m"));
		Join root = new Join(outer, new Join(correlated, right));

		AtomicInteger independentInvocationCount = new AtomicInteger();
		AtomicInteger independentNextCount = new AtomicInteger();
		AtomicInteger independentCloseCount = new AtomicInteger();
		List<Value> correlatedInputs = new ArrayList<>();
		List<BindingSet> independentRows = List.of(row("r", "urn:test:r1"), row("r", "urn:test:r2"),
				row("r", "urn:test:r3"));
		FederatedService correlatedService = mock(FederatedService.class);
		when(correlatedService.select(eq(correlated), anySet(), any(BindingSet.class), eq(correlated.getBaseURI())))
				.thenAnswer(invocation -> {
					BindingSet requested = invocation.getArgument(2);
					Value requestedX = requested.getValue("x");
					assertNotNull(requestedX, "the correlated SERVICE must receive each outer x binding");
					correlatedInputs.add(requestedX);
					if (xA.equals(requestedX)) {
						return new EmptyIteration<>();
					}
					assertEquals(xB, requestedX);
					assertEquals(1, independentInvocationCount.get(),
							"the empty first correlated row must trigger the independent fallback first");
					assertTrue(independentNextCount.get() <= 1,
							"the empty-left fallback must consume at most one independent row");
					return fixedRows(mergeBindings(requested, row("lo", "urn:test:lo-b")))
							.evaluate(EmptyBindingSet.getInstance());
				});

		FederatedService independentService = mock(FederatedService.class);
		when(independentService.select(eq(independent), anySet(), any(BindingSet.class), eq(independent.getBaseURI())))
				.thenAnswer(invocation -> {
					independentInvocationCount.incrementAndGet();
					BindingSet requested = invocation.getArgument(2);
					return new CloseableIteration<>() {
						private int index;

						@Override
						public boolean hasNext() {
							return index < independentRows.size();
						}

						@Override
						public BindingSet next() {
							if (index >= independentRows.size()) {
								throw new NoSuchElementException();
							}
							independentNextCount.incrementAndGet();
							return mergeBindings(requested, independentRows.get(index++));
						}

						@Override
						public void remove() {
							throw new UnsupportedOperationException();
						}

						@Override
						public void close() {
							independentCloseCount.incrementAndGet();
						}
					};
				});

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), serviceUrl -> {
			if (correlatedEndpoint.stringValue().equals(serviceUrl)) {
				return correlatedService;
			}
			if (independentEndpoint.stringValue().equals(serviceUrl)) {
				return independentService;
			}
			throw new QueryEvaluationException("unexpected SERVICE endpoint: " + serviceUrl);
		});

		List<BindingSet> rows = collect(strategy.precompile(root).evaluate(EmptyBindingSet.getInstance()));

		assertEquals(List.of(xA, xB), correlatedInputs,
				"the correlated SERVICE must retain the outer input order");
		assertEquals(4, rows.size(), "only the later correlated row can join the independent UNION");
		assertTrue(rows.stream().allMatch(row -> xB.equals(row.getValue("x"))));
		assertEquals(Set.of(valueFactory.createIRI("urn:test:r1"), valueFactory.createIRI("urn:test:r2"),
				valueFactory.createIRI("urn:test:r3")),
				rows.stream()
						.map(row -> row.getValue("r"))
						.filter(Objects::nonNull)
						.collect(Collectors.toSet()));
		assertEquals(1, rows.stream()
				.filter(row -> valueFactory.createIRI("urn:test:m").equals(row.getValue("marker")))
				.count());
		assertEquals(1, independentInvocationCount.get());
		assertEquals(3, independentNextCount.get());
		assertEquals(1, independentCloseCount.get());
	}

	@ParameterizedTest(name = "independentFirst={0}")
	@ValueSource(booleans = { true, false })
	void emptyCorrelatedPrefixWithServiceUnionPreservesLaterRows(boolean independentFirst) {
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		IRI prefixEndpoint = valueFactory.createIRI("urn:test:prefix-left");
		IRI independentEndpoint = valueFactory.createIRI("urn:test:prefix-independent");
		IRI correlatedEndpoint = valueFactory.createIRI("urn:test:prefix-correlated");
		IRI xA = valueFactory.createIRI("urn:test:prefix-a");
		IRI xB = valueFactory.createIRI("urn:test:prefix-b");
		Service prefix = new Service(Var.of("serviceRefA", prefixEndpoint),
				new StatementPattern(Var.of("x"), Var.of("xp"), Var.of("xo")),
				"{ ?x ?xp ?xo }", Map.of(), null, false);
		Service independent = new Service(Var.of("serviceRefB", independentEndpoint),
				new StatementPattern(Var.of("r"), Var.of("rp"), Var.of("ro")),
				"{ ?r ?rp ?ro }", Map.of(), null, false);
		Service correlated = new Service(Var.of("serviceRefC", correlatedEndpoint),
				new StatementPattern(Var.of("x"), Var.of("cp"), Var.of("co")),
				"{ ?x ?cp ?co }", Map.of(), null, false);
		BindingSetAssignment outer = new BindingSetAssignment();
		outer.setBindingSets(List.of(row("x", xA), row("x", xB)));
		Union right = independentFirst ? new Union(independent, correlated) : new Union(correlated, independent);
		Join root = new Join(outer, new Join(prefix, right));

		AtomicInteger independentInvocationCount = new AtomicInteger();
		AtomicInteger independentNextCount = new AtomicInteger();
		AtomicInteger independentCloseCount = new AtomicInteger();
		List<Value> prefixInputs = new ArrayList<>();
		List<Value> correlatedInputs = new ArrayList<>();
		List<BindingSet> independentRows = List.of(row("r", "urn:test:prefix-r1"),
				row("r", "urn:test:prefix-r2"), row("r", "urn:test:prefix-r3"));
		FederatedService prefixService = mock(FederatedService.class);
		when(prefixService.select(eq(prefix), anySet(), any(BindingSet.class), eq(prefix.getBaseURI())))
				.thenAnswer(invocation -> {
					BindingSet requested = invocation.getArgument(2);
					Value requestedX = requested.getValue("x");
					assertNotNull(requestedX, "the prefix SERVICE must receive each outer x binding");
					prefixInputs.add(requestedX);
					if (xA.equals(requestedX)) {
						return new EmptyIteration<>();
					}
					assertEquals(xB, requestedX);
					assertEquals(1, independentInvocationCount.get(),
							"the empty prefix must trigger the independent SERVICE probe first");
					assertTrue(independentNextCount.get() <= 1,
							"the empty prefix probe must consume at most one independent row");
					assertEquals(0, correlatedInputs.size(),
							"the correlated UNION arm must not receive an unconstrained probe");
					return fixedRows(mergeBindings(requested, row("xo", "urn:test:prefix-object")))
							.evaluate(EmptyBindingSet.getInstance());
				});

		FederatedService correlatedService = mock(FederatedService.class);
		when(correlatedService.select(eq(correlated), anySet(), any(BindingSet.class), eq(correlated.getBaseURI())))
				.thenAnswer(invocation -> {
					BindingSet requested = invocation.getArgument(2);
					Value requestedX = requested.getValue("x");
					assertNotNull(requestedX, "the correlated SERVICE must never receive an unbound x");
					correlatedInputs.add(requestedX);
					assertEquals(xB, requestedX);
					return fixedRows(mergeBindings(requested, row("co", "urn:test:prefix-correlated-object")))
							.evaluate(EmptyBindingSet.getInstance());
				});

		FederatedService independentService = mock(FederatedService.class);
		when(independentService.select(eq(independent), anySet(), any(BindingSet.class), eq(independent.getBaseURI())))
				.thenAnswer(invocation -> {
					independentInvocationCount.incrementAndGet();
					BindingSet requested = invocation.getArgument(2);
					return new CloseableIteration<>() {
						private int index;

						@Override
						public boolean hasNext() {
							return index < independentRows.size();
						}

						@Override
						public BindingSet next() {
							if (index >= independentRows.size()) {
								throw new NoSuchElementException();
							}
							independentNextCount.incrementAndGet();
							return mergeBindings(requested, independentRows.get(index++));
						}

						@Override
						public void remove() {
							throw new UnsupportedOperationException();
						}

						@Override
						public void close() {
							independentCloseCount.incrementAndGet();
						}
					};
				});

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), serviceUrl -> {
			if (prefixEndpoint.stringValue().equals(serviceUrl)) {
				return prefixService;
			}
			if (correlatedEndpoint.stringValue().equals(serviceUrl)) {
				return correlatedService;
			}
			if (independentEndpoint.stringValue().equals(serviceUrl)) {
				return independentService;
			}
			throw new QueryEvaluationException("unexpected SERVICE endpoint: " + serviceUrl);
		});

		List<BindingSet> rows = collect(strategy.precompile(root).evaluate(EmptyBindingSet.getInstance()));

		assertEquals(List.of(xA, xB), prefixInputs,
				"the prefix SERVICE must retain both outer mappings after the empty first row");
		assertEquals(List.of(xB), correlatedInputs,
				"the correlated UNION arm must run only for the later bound prefix row");
		assertEquals(4, rows.size(), "no independent or later correlated rows may be lost after the probe");
		assertTrue(rows.stream().allMatch(row -> xB.equals(row.getValue("x"))),
				"every surviving UNION result must retain the later outer mapping");
		assertEquals(3, rows.stream().filter(row -> row.getValue("r") != null).count());
		assertEquals(1, rows.stream().filter(row -> row.getValue("co") != null).count());
		assertEquals(Set.of(valueFactory.createIRI("urn:test:prefix-r1"),
				valueFactory.createIRI("urn:test:prefix-r2"), valueFactory.createIRI("urn:test:prefix-r3")),
				rows.stream().map(row -> row.getValue("r")).filter(Objects::nonNull).collect(Collectors.toSet()));
		assertEquals(1, independentInvocationCount.get(),
				"the independent SERVICE arm must be evaluated once across both outer mappings");
		assertEquals(3, independentNextCount.get());
		assertEquals(1, independentCloseCount.get());
	}

