	@Test
	void closingMixedUnionCancelsActiveIndependentReplayProducer() throws Exception {
		Service mappingBranch = new Service(
				Var.of("serviceRef", SimpleValueFactory.getInstance().createIRI("urn:test:blocking-mapping")),
				new StatementPattern(Var.of("x"), Var.of("predicate"), Var.of("object")),
				"{ ?x ?predicate ?object }", Map.of(), null, false);
		Extension independentBranch = independentUuidBranch();
		Union mixedUnion = new Union(mappingBranch, independentBranch);
		BindingSetAssignment left = values("x", "one");
		Join join = new Join(left, mixedUnion);
		CountDownLatch producerStarted = new CountDownLatch(1);
		CountDownLatch releaseProducer = new CountDownLatch(1);
		AtomicInteger producerCloseCount = new AtomicInteger();

		DefaultEvaluationStrategy strategy = defaultStrategySpy();
		doReturn(fixedRows("x", "urn:test:one")).when(strategy)
				.precompile(same(left),
						any(QueryEvaluationContext.class));
		doReturn(QueryEvaluationStep.empty()).when(strategy)
				.precompile(same(mappingBranch),
						any(QueryEvaluationContext.class));
		doReturn((QueryEvaluationStep) bindings -> new BlockingReplayProducer(producerStarted, releaseProducer,
				producerCloseCount)).when(strategy)
						.precompile(same(independentBranch.getArg()),
								any(QueryEvaluationContext.class));

		JoinQueryEvaluationStep step = new JoinQueryEvaluationStep(strategy, join, mergeContext());
		CloseableIteration<BindingSet> result = step.evaluate(EmptyBindingSet.getInstance());
		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<Boolean> consumer = executor.submit(result::hasNext);
		Future<?> closer = null;
		CountDownLatch closeFinished = new CountDownLatch(1);
		try {
			assertTrue(producerStarted.await(5, TimeUnit.SECONDS), "the replay producer must become active");
			closer = executor.submit(() -> {
				try {
					result.close();
				} finally {
					closeFinished.countDown();
				}
			});
			assertTrue(closeFinished.await(5, TimeUnit.SECONDS),
					"closing the result must close a blocking replay producer");
		} finally {
			releaseProducer.countDown();
			try {
				consumer.get(5, TimeUnit.SECONDS);
			} finally {
				try {
					if (closer != null) {
						closer.get(5, TimeUnit.SECONDS);
					}
				} finally {
					try {
						result.close();
					} finally {
						executor.shutdownNow();
						executor.awaitTermination(5, TimeUnit.SECONDS);
					}
				}
			}
		}
		assertEquals(1, producerCloseCount.get(), "the active producer must be closed exactly once");
	}

