	@Test
	void preparedMixedUnionProductionPathPromotesProbeRowsBeforeNormalConsumption() {
		Service service = mappingService("urn:test:probe-normal-production-path");
		Extension independent = independentUuidBranch();
		Union union = new Union(service, independent);
		BindingSetAssignment outer = new BindingSetAssignment();
		outer.setBindingSets(List.of(row("x", "urn:test:one"), row("x", "urn:test:two")));
		Join join = new Join(outer, union);
		FederatedService federatedService = mock(FederatedService.class);
		when(federatedService.select(eq(service), anySet(), any(BindingSet.class), eq(service.getBaseURI())))
				.thenReturn(new EmptyIteration<>());
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(),
				serviceUrl -> federatedService);
		ScopedEvaluationStep scoped = ScopedEvaluationStep.adapt(join, strategy.precompile(join));
		ScopedEvaluationOwner owner = ScopedEvaluationOwner.root(EmptyBindingSet.getInstance());
		try {
			List<BindingSet> probed = collect(
					scoped.evaluateScoped(owner.probeView(), EmptyBindingSet.getInstance(), Set.of()));
			List<BindingSet> consumed = collect(scoped.evaluateScoped(owner, EmptyBindingSet.getInstance(), Set.of()));

			assertEquals(2, probed.size(),
					"the production prepared path must return both outer mappings during probing");
			assertEquals(probed, consumed, "the production scoped path must promote probe rows for normal consumers");
			assertEquals(1L, probed.stream().map(row -> row.getValue("u")).distinct().count());
			assertEquals(1L, consumed.stream().map(row -> row.getValue("u")).distinct().count());
		} finally {
			owner.close();
		}
	}

