	@Test
	void localSubqueryDoesNotReadOuterBindingThroughBoundFilter() {
		Service mappingBranch = new Service(
				Var.of("serviceRef", SimpleValueFactory.getInstance().createIRI("urn:test:bound-filter-mapping")),
				new StatementPattern(Var.of("x"), Var.of("predicate"), Var.of("object")),
				"{ ?x ?predicate ?object }", Map.of(), null, false);
		Extension localExtension = new Extension(new SingletonSet(), new ExtensionElem(Var.of("x"), "u"));
		Projection localSubquery = new Projection(localExtension,
				new ProjectionElemList(new ProjectionElem("u")));
		Union mixedUnion = new Union(mappingBranch, localSubquery);
		Filter filtered = new Filter(mixedUnion, new Bound(Var.of("u")));
		BindingSet unboundX = new ListBindingSet(List.of("x"), Collections.singletonList((Value) null));
		BindingSetAssignment outer = new BindingSetAssignment();
		outer.setBindingSets(List.of(unboundX, row("x", "urn:test:bound")));
		Join join = new Join(outer, filtered);

		AtomicInteger localEvaluationCount = new AtomicInteger();
		DefaultEvaluationStrategy strategy = defaultStrategySpy();
		doReturn((QueryEvaluationStep) bindings -> new EmptyIteration<>()).when(strategy)
				.precompile(same(mappingBranch), any(QueryEvaluationContext.class));
		doReturn((QueryEvaluationStep) bindings -> {
			localEvaluationCount.incrementAndGet();
			assertFalse(bindings.hasBinding("x"), "a local subquery must not receive the outer x binding");
			return fixedRows(EmptyBindingSet.getInstance()).evaluate(bindings);
		}).when(strategy).precompile(same(localExtension.getArg()), any(QueryEvaluationContext.class));
		List<BindingSet> rows = collect(new JoinQueryEvaluationStep(strategy, join, mergeContext())
				.evaluate(EmptyBindingSet.getInstance()));

		assertEquals(0, rows.size(), "BOUND must reject the unbound local subquery result");
		assertEquals(1, localEvaluationCount.get(),
				"a local subquery independent of the outer mapping must be evaluated once");
	}

