	@Test
	void stagedWrappersCloseTheCurrentIterationOnceAndPreserveFailureSuppression() {
		AtomicInteger closeCount = new AtomicInteger();
		RuntimeException cleanupFailure = new RuntimeException("cleanup failure");
		CloseableIteration<BindingSet> base = new CloseableIteration<>() {
			private boolean available = true;

			@Override
			public boolean hasNext() {
				return available;
			}

			@Override
			public BindingSet next() {
				if (!available) {
					throw new NoSuchElementException();
				}
				available = false;
				return EmptyBindingSet.getInstance();
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}

			@Override
			public void close() {
				if (closeCount.incrementAndGet() == 1) {
					throw cleanupFailure;
				}
				throw new AssertionError("the base iteration was closed more than once");
			}
		};
		Error wrapperFailure = new AssertionError("wrapper failure");
		QueryEvaluationStep staged = ScopedEvaluationStep.withConsumptionWrapper(new SingletonSet(), ignored -> base,
				iteration -> iteration);
		staged = QueryEvaluationStep.wrap(staged, iteration -> iteration);
		staged = QueryEvaluationStep.wrap(staged, iteration -> {
			throw wrapperFailure;
		});
		QueryEvaluationStep finalStaged = staged;

		Error actual = assertThrows(Error.class, () -> finalStaged.evaluate(EmptyBindingSet.getInstance()));

		assertSame(wrapperFailure, actual);
		assertEquals(1, closeCount.get(), "staged wrapper failure must close the current iteration once");
		assertEquals(1, wrapperFailure.getSuppressed().length);
		assertSame(cleanupFailure, wrapperFailure.getSuppressed()[0]);
	}

	@Test
	void directServiceConstructorFailureClosesTransferredLeftExactlyOnce() {
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingSets(List.of(EmptyBindingSet.getInstance()));
		Service service = mappingService("urn:test:constructor-failure");
		AtomicInteger closeCount = new AtomicInteger();
		CloseableIteration<BindingSet> leftIteration = new CloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return true;
			}

			@Override
			public BindingSet next() {
				return EmptyBindingSet.getInstance();
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}

			@Override
			public void close() {
				if (closeCount.incrementAndGet() > 1) {
					throw new AssertionError("the SERVICE input was closed more than once");
				}
			}
		};
		AssertionError expected = new AssertionError("SERVICE constructor failure");
		EvaluationStrategy strategy = mock(EvaluationStrategy.class);
		when(strategy.precompile(same(left), any(QueryEvaluationContext.class))).thenReturn(ignored -> leftIteration);
		when(strategy.precompile(same(service), any(QueryEvaluationContext.class)))
				.thenReturn(QueryEvaluationStep.empty());
		when(strategy.getService(service.getServiceRef().getValue().stringValue())).thenThrow(expected);

		JoinQueryEvaluationStep step = new JoinQueryEvaluationStep(strategy, new Join(left, service), mergeContext());

		AssertionError actual = assertThrows(AssertionError.class,
				() -> step.evaluate(EmptyBindingSet.getInstance()));

		assertSame(expected, actual);
		assertEquals(1, closeCount.get(), "a SERVICE constructor failure must transfer left ownership once");
	}

