	void emptyJoinProbesOutputOnlyServiceWithoutUnboundCorrelatedService(boolean outputOnlyFirst) {
		Service outputOnly = new Service(
				Var.of("serviceRef", SimpleValueFactory.getInstance().createIRI("urn:test:output-only-service")),
				new Extension(new SingletonSet(), new ExtensionElem(new FunctionCall("STRUUID"), "u")),
				"{ BIND(STRUUID() AS ?u) }", Map.of(), null, false);
		Service correlated = mappingService("urn:test:output-correlated-service");
		assertTrue(outputOnly.getServiceInputBindingNames().isEmpty(),
				"the BIND target is an output, not an enclosing SERVICE input dependency");
		assertTrue(outputOnly.getServiceOutputBindingNames().contains("u"));
		Union union = outputOnlyFirst ? new Union(outputOnly, correlated) : new Union(correlated, outputOnly);
		BindingSetAssignment emptyLeft = new BindingSetAssignment();
		emptyLeft.setBindingNames(Set.of("x"));
		emptyLeft.setBindingSets(List.of());
		Join root = new Join(emptyLeft, union);

		AtomicInteger outputCalls = new AtomicInteger();
		AtomicInteger correlatedCalls = new AtomicInteger();
		QueryEvaluationException expected = new QueryEvaluationException("output-only SERVICE failed");
		FederatedService outputService = mock(FederatedService.class);
		when(outputService.ask(eq(outputOnly), any(BindingSet.class), eq(outputOnly.getBaseURI())))
				.thenAnswer(invocation -> {
					outputCalls.incrementAndGet();
					throw expected;
				});
		when(outputService.select(eq(outputOnly), anySet(), any(BindingSet.class), eq(outputOnly.getBaseURI())))
				.thenAnswer(invocation -> {
					outputCalls.incrementAndGet();
					throw expected;
				});
		when(outputService.evaluate(eq(outputOnly), any(CloseableIteration.class), eq(outputOnly.getBaseURI())))
				.thenAnswer(invocation -> {
					CloseableIteration<BindingSet> input = invocation.getArgument(1);
					try {
						if (!input.hasNext()) {
							return new EmptyIteration<>();
						}
						outputCalls.incrementAndGet();
						throw expected;
					} finally {
						input.close();
					}
				});

		FederatedService correlatedService = mock(FederatedService.class);
		when(correlatedService.ask(eq(correlated), any(BindingSet.class), eq(correlated.getBaseURI())))
				.thenAnswer(invocation -> {
					correlatedCalls.incrementAndGet();
					return false;
				});
		when(correlatedService.select(eq(correlated), anySet(), any(BindingSet.class), eq(correlated.getBaseURI())))
				.thenAnswer(invocation -> {
					correlatedCalls.incrementAndGet();
					return new EmptyIteration<>();
				});
		when(correlatedService.evaluate(eq(correlated), any(CloseableIteration.class), eq(correlated.getBaseURI())))
				.thenAnswer(invocation -> {
					CloseableIteration<BindingSet> input = invocation.getArgument(1);
					try {
						if (!input.hasNext()) {
							return new EmptyIteration<>();
						}
						correlatedCalls.incrementAndGet();
						while (input.hasNext()) {
							input.next();
						}
						return new EmptyIteration<>();
					} finally {
						input.close();
					}
				});

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), serviceUrl -> {
			if ("urn:test:output-only-service".equals(serviceUrl)) {
				return outputService;
			}
			if ("urn:test:output-correlated-service".equals(serviceUrl)) {
				return correlatedService;
			}
			throw new QueryEvaluationException("unexpected SERVICE endpoint: " + serviceUrl);
		});

		QueryEvaluationException actual = assertThrows(QueryEvaluationException.class,
				() -> collect(strategy.precompile(root).evaluate(EmptyBindingSet.getInstance())));

		assertSame(expected, actual);
		assertEquals(1, outputCalls.get(), "the independent output-only SERVICE must be probed once");
		assertEquals(0, correlatedCalls.get(),
				"the correlated SERVICE must not receive the empty canonical probe mapping");
	}

